def fact(n):
    f = 1
    for i in range(1,n+1):
        f*=i
    return f

def choose(n,k):
    if k == 1:
        return fact(n)/fact(k)
    elif n==k:
        return fact(k)
    return fact(n)/(fact(k)*fact(n-k))

