def find_string_matches(s, term):
    char_counts = dict.fromkeys(list(s), 0)
    term_counts = dict.fromkeys(list(term), 0)

    start = end = None
    i = 0

    while i < len(s):
        if s[i] in char_counts:
            char_counts[s[i]] += 1
            if term_counts[s[i]] > 0:
                end = i
                term_counts[s[i]] += 1
                if end - start + 1 == len(term) and all(v == 1 for v in term_counts.values()):
                    return (start, end)
            if char_counts[s[i]] > term_counts[s[i]]:
                start = end
            elif end is not None:
                end += 1
        i += 1

    return (-1, -1)
